from pathlib import Path


def replace_once(text: str, old: str, new: str, label: str) -> str:
    count = text.count(old)
    if count != 1:
        raise SystemExit(f'{label}: expected exactly one match, found {count}')
    return text.replace(old, new, 1)

path = Path('core/channels/channel-binding.ts')
text = path.read_text()
old = """  const workspaceChannelAliases = new Map(sourceToLogicalChannelId);\n  for (const entry of catalog.entries) {\n    if (boundByLogicalKey.has(entry.logicalKey)) continue;\n    const target = chooseWorkspaceAliasTarget(\n      boundDisplayIndex.get(normalized(entry.displayName)),\n      entry,\n    );\n    if (target) {\n      workspaceChannelAliases.set(stableId(entry.logicalKey), stableId(target.logicalKey));\n    }\n  }\n\n  const dataSource = new BoundNumericChannelDataSource(sourceData, logicalToSourceChannelId);\n"""
new = """  const workspaceChannelAliases = new Map(sourceToLogicalChannelId);\n  for (const entry of catalog.entries) {\n    if (boundByLogicalKey.has(entry.logicalKey)) continue;\n    const target = chooseWorkspaceAliasTarget(\n      boundDisplayIndex.get(normalized(entry.displayName)),\n      entry,\n    );\n    if (target) {\n      workspaceChannelAliases.set(stableId(entry.logicalKey), stableId(target.logicalKey));\n    }\n  }\n\n  // Older browser workspaces used short user-facing channel names such as\n  // `ini:rpm` or `ini:iat` rather than INI logical keys. Those IDs are not\n  // catalog entries, so the stale-known migration above cannot see them.\n  // Add a legacy shorthand alias only when the normalized display label maps\n  // to exactly one currently bound INI channel and does not collide with a\n  // real current INI logical key.\n  for (const [displayIdentity, candidates] of boundDisplayIndex) {\n    if (candidates.length != 1) continue;\n    if (keyIndex.has(displayIdentity)) continue;\n    const target = candidates[0];\n    if (!target) continue;\n    const legacyId = `ini:${displayIdentity}`;\n    const targetId = stableId(target.logicalKey);\n    if (legacyId !== targetId && !workspaceChannelAliases.has(legacyId)) {\n      workspaceChannelAliases.set(legacyId, targetId);\n    }\n  }\n\n  const dataSource = new BoundNumericChannelDataSource(sourceData, logicalToSourceChannelId);\n"""
text = replace_once(text, old, new, 'legacy shorthand alias block')
path.write_text(text)

path = Path('tests/channels/channel-binding.test.ts')
text = path.read_text()
needle = """  it('leaves ambiguous duplicate labels as log-only when unit cannot resolve them', () => {\n"""
insert = """  it('maps legacy shorthand workspace IDs from unique bound INI display labels', () => {\n    const source = new FakeDataSource();\n    const entries = [\n      {\n        logicalKey: 'RPMValue',\n        sourceName: 'RPMValue',\n        displayName: 'RPM',\n        valueType: 'integer' as const,\n        unit: 'RPM',\n        availability: 'known-no-data' as const,\n        provenance: { kind: 'ini' as const },\n      },\n      {\n        logicalKey: 'MAPValue',\n        sourceName: 'MAPValue',\n        displayName: 'MAP',\n        valueType: 'number' as const,\n        unit: 'kPa',\n        availability: 'known-no-data' as const,\n        provenance: { kind: 'ini' as const },\n      },\n      {\n        logicalKey: 'TPSValue',\n        sourceName: 'TPSValue',\n        displayName: 'TPS',\n        valueType: 'number' as const,\n        unit: '%',\n        availability: 'known-no-data' as const,\n        provenance: { kind: 'ini' as const },\n      },\n      {\n        logicalKey: 'intake',\n        sourceName: 'intake',\n        displayName: 'IAT',\n        valueType: 'number' as const,\n        unit: 'deg C',\n        availability: 'known-no-data' as const,\n        provenance: { kind: 'ini' as const },\n      },\n      {\n        logicalKey: 'coolant',\n        sourceName: 'coolant',\n        displayName: 'CLT',\n        valueType: 'number' as const,\n        unit: 'deg C',\n        availability: 'known-no-data' as const,\n        provenance: { kind: 'ini' as const },\n      },\n    ];\n    const aliasCatalog: ChannelCatalog = {\n      entries,\n      byLogicalKey: new Map(entries.map((entry) => [entry.logicalKey, entry] as const)),\n    };\n\n    const result = bindChannelCatalogToLog(\n      aliasCatalog,\n      [\n        { id: 'mlg:0', sourceName: 'RPM', displayName: 'RPM', valueType: 'integer', unit: 'RPM' },\n        { id: 'mlg:1', sourceName: 'MAP', displayName: 'MAP', valueType: 'number', unit: 'kPa' },\n        { id: 'mlg:2', sourceName: 'TPS', displayName: 'TPS', valueType: 'number', unit: '%' },\n        { id: 'mlg:3', sourceName: 'IAT', displayName: 'IAT', valueType: 'number', unit: 'deg C' },\n        { id: 'mlg:4', sourceName: 'CLT', displayName: 'CLT', valueType: 'number', unit: 'deg C' },\n      ],\n      source,\n    );\n\n    expect(result.workspaceChannelAliases.get('ini:rpm')).toBe('ini:RPMValue');\n    expect(result.workspaceChannelAliases.get('ini:map')).toBe('ini:MAPValue');\n    expect(result.workspaceChannelAliases.get('ini:tps')).toBe('ini:TPSValue');\n    expect(result.workspaceChannelAliases.get('ini:iat')).toBe('ini:intake');\n    expect(result.workspaceChannelAliases.has('ini:coolant')).toBe(false);\n  });\n\n  it('does not create a shorthand alias when the display label collides with a real INI key', () => {\n    const source = new FakeDataSource();\n    const entries = [\n      {\n        logicalKey: 'rpm',\n        sourceName: 'rpm',\n        displayName: 'Legacy RPM',\n        valueType: 'integer' as const,\n        unit: 'RPM',\n        availability: 'known-no-data' as const,\n        provenance: { kind: 'ini' as const },\n      },\n      {\n        logicalKey: 'RPMValue',\n        sourceName: 'RPMValue',\n        displayName: 'RPM',\n        valueType: 'integer' as const,\n        unit: 'RPM',\n        availability: 'known-no-data' as const,\n        provenance: { kind: 'ini' as const },\n      },\n    ];\n    const aliasCatalog: ChannelCatalog = {\n      entries,\n      byLogicalKey: new Map(entries.map((entry) => [entry.logicalKey, entry] as const)),\n    };\n\n    const result = bindChannelCatalogToLog(\n      aliasCatalog,\n      [{ id: 'mlg:0', sourceName: 'RPMValue', displayName: 'RPMValue', valueType: 'integer', unit: 'RPM' }],\n      source,\n    );\n\n    expect(result.workspaceChannelAliases.has('ini:rpm')).toBe(false);\n  });\n\n""" + needle
text = replace_once(text, needle, insert, 'legacy shorthand tests')
path.write_text(text)
